<?php
/** v2 拼团：终态不可逆；团锁之后只允许写本单席位，不扩大订单和资金锁集合。 */
class GroupService
{
    private $pdo;
    public function __construct($pdo){$this->pdo=$pdo;}
    private function row($sql,$args=array()){$s=$this->pdo->prepare($sql);$s->execute($args);return $s->fetch();}
    private function rows($sql,$args=array()){$s=$this->pdo->prepare($sql);$s->execute($args);return $s->fetchAll();}
    private function exec($sql,$args=array()){$s=$this->pdo->prepare($sql);$s->execute($args);return $s;}
    public function now(){return $this->pdo->query('SELECT NOW()')->fetchColumn();}
    private function transactionRequired(){if(!$this->pdo->inTransaction())throw new LogicException('拼团操作必须处于订单事务内。');}
    private function activityEnabled(){return (bool)$this->row('SELECT id FROM activity_settings WHERE activity_key="group" AND status="enabled" AND (start_at IS NULL OR start_at<=NOW()) AND (end_at IS NULL OR NOW()<end_at)');}
    private function usable($g,$now){return $g&&(int)$g['flow_version']===2&&$g['status']==='forming'&&(!$g['starts_at']||$g['starts_at']<=$now)&&(!$g['expires_at']||$now<$g['expires_at']);}
    public function isV2($orderId){$r=$this->row('SELECT g.flow_version FROM group_orders go JOIN group_campaigns g ON g.id=go.campaign_id WHERE go.order_id=?',array($orderId));return $r&&(int)$r['flow_version']===2;}
    public function createGroup($uid,$planId){
        $this->pdo->beginTransaction();try{
            $this->exec('SELECT id FROM users WHERE id=? AND status="active" FOR UPDATE',array($uid));
            $a=$this->row('SELECT * FROM activity_settings WHERE activity_key="group" AND status="enabled" AND (start_at IS NULL OR start_at<=NOW()) AND (end_at IS NULL OR NOW()<end_at) FOR UPDATE');
            if(!$a)throw new RuntimeException('好友拼单当前未开启。');
            $cfg=array_merge((new ActivityService($this->pdo))->defaults('group')['config'],(array)json_decode($a['config_json'],true));$ids=array_values(array_unique(array_filter(array_map('intval',isset($cfg['plan_ids'])?(array)$cfg['plan_ids']:array()))));
            if(!in_array((int)$planId,$ids,true))throw new RuntimeException('所选方案未开放拼团。');
            $plans=$this->rows('SELECT pp.*,p.name product_name FROM product_plans pp JOIN products p ON p.id=pp.product_id WHERE pp.id IN ('.implode(',',array_fill(0,count($ids),'?')).') AND pp.status="active" AND p.status="active" AND p.product_type="vpn"',$ids);
            if(count($plans)!==count($ids))throw new RuntimeException('活动包含不可用方案，请联系管理员。');$plan=null;foreach($plans as $p)if((int)$p['id']===(int)$planId)$plan=$p;
            $now=$this->now();$hours=max(1,min(720,(int)$cfg['duration_hours']));$discount=max(0,min(100,(int)$cfg['discount_percent']));$minutes=15;
            $this->exec('INSERT INTO group_campaigns(campaign_no,activity_id,creator_user_id,product_id,title,target_members,flow_version,discount_percent_snapshot,reservation_minutes,status,starts_at,expires_at,created_at,updated_at) VALUES(?,?,?,?,?,?,2,?, ?,"forming",?,DATE_ADD(?,INTERVAL '.$hours.' HOUR),?,?)',array('GP'.bin2hex(random_bytes(12)),$a['id'],$uid,$plan['product_id'],$plan['product_name'].' · 好友拼单',max(2,min(100,(int)$cfg['target_members'])),$discount,$minutes,$now,$now,$now,$now));$id=(int)$this->pdo->lastInsertId();
            foreach($ids as $pid)$this->exec('INSERT INTO group_campaign_plans(campaign_id,product_plan_id,created_at) VALUES(?,?,?)',array($id,$pid,$now));
            $this->exec('INSERT INTO group_members(campaign_id,user_id,role,status,joined_at) VALUES(?,?,"leader","pending",?)',array($id,$uid,$now));$this->pdo->commit();return $id;
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
    public function joinGroup($gid,$uid,$planId){
        $this->pdo->beginTransaction();try{
            $this->exec('SELECT id FROM users WHERE id=? AND status="active" FOR UPDATE',array($uid));
            $g=$this->row('SELECT * FROM group_campaigns WHERE id=? FOR UPDATE',array($gid));$now=$this->now();$m=$this->row('SELECT * FROM group_members WHERE campaign_id=? AND user_id=?',array($gid,$uid));
            if(!$this->usable($g,$now))throw new RuntimeException('拼团属于历史流程、已结束或已过期。');
            if(!$m&&!$this->activityEnabled())throw new RuntimeException('好友拼单当前未开启。');
            if(!$this->row('SELECT pp.id FROM group_campaign_plans gp JOIN product_plans pp ON pp.id=gp.product_plan_id JOIN products p ON p.id=pp.product_id WHERE gp.campaign_id=? AND pp.id=? AND pp.status="active" AND p.status="active" AND p.product_type="vpn"',array($gid,$planId)))throw new RuntimeException('该团不允许所选方案。');
            if($m&&$m['status']==='cancelled')throw new RuntimeException('已退出该团，请参加其他团。');
            if(!$m)$this->exec('INSERT INTO group_members(campaign_id,user_id,role,status,joined_at) VALUES(?,?,"member","pending",?)',array($gid,$uid,$now));
            $p=$this->row('SELECT product_id FROM product_plans WHERE id=?',array($planId));$this->pdo->commit();return array('status'=>$g['status'],'current_members'=>(int)$g['current_members'],'target_members'=>(int)$g['target_members'],'product_id'=>(int)$p['product_id']);
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
    // 同团同用户唯一，调用方已持有用户锁；这里只读取既有订单，不倒序加锁。
    public function existingOrder($gid,$uid){return $this->row('SELECT o.order_no,o.status FROM group_orders go JOIN orders o ON o.id=go.order_id WHERE go.campaign_id=? AND go.user_id=?',array($gid,$uid));}
    public function preparePromotion($gid,$uid,$planId,$amount,$lock=false){
        $this->transactionRequired();$g=$this->row('SELECT * FROM group_campaigns WHERE id=?'.($lock?' FOR UPDATE':''),array($gid));$now=$this->now();
        if(!$this->usable($g,$now)||!$this->activityEnabled())throw new RuntimeException('拼团已结束、历史流程或活动已关闭。');
        $m=$this->row('SELECT * FROM group_members WHERE campaign_id=? AND user_id=?'.($lock?' FOR UPDATE':''),array($gid,$uid));
        if(!$m||$m['status']!=='pending'||!empty($m['group_order_id']))throw new RuntimeException('该用户已有订单或已退出，请参加其他团。');
        if(!$this->row('SELECT gp.product_plan_id FROM group_campaign_plans gp JOIN product_plans pp ON pp.id=gp.product_plan_id JOIN products p ON p.id=pp.product_id WHERE gp.campaign_id=? AND gp.product_plan_id=? AND p.product_type="vpn"',array($gid,$planId)))throw new RuntimeException('方案不在该团快照中。');
        // 只计有效占位；过期订单由逐单任务清理，不在团锁内锁其他订单。
        $n=$this->row('SELECT COUNT(*) n FROM group_orders WHERE campaign_id=? AND (status IN ("paid","released") OR (status="pending" AND NOW()<reserved_until))',array($gid));
        if((int)$n['n']>=(int)$g['target_members'])throw new RuntimeException('拼团名额已满。');
        if($lock)$this->exec('UPDATE group_campaigns SET reserved_members=?,updated_at=? WHERE id=?',array((int)$n['n']+1,$now,$gid));
        $g['member_user_id']=$uid;$g['member_role']=$m['role'];$g['member_id']=$m['id'];$percent=(int)$g['discount_percent_snapshot'];$total=intdiv($amount,100)*$percent+intdiv(($amount%100)*$percent,100);
        return array('discount'=>$amount-$total,'group'=>$g,'promotion_code'=>'group:'.$gid);
    }
    public function attachOrder($orderId,$promotion){$this->transactionRequired();$old=$promotion;$g=$promotion['group'];$order=$this->row('SELECT * FROM orders WHERE id=?',array($orderId));if(!$order||$order['product_type_snapshot']!=='vpn')throw new RuntimeException('账号订单不能绑定拼团。');$promotion=$this->preparePromotion($g['id'],$g['member_user_id'],$order['product_plan_id'],(int)$order['original_amount_cents'],true);if((int)$promotion['discount']!==(int)$old['discount'])throw new RuntimeException('拼团快照已变化，请重新下单。');$g=$promotion['group'];$now=$this->now();$until=date('Y-m-d H:i:s',strtotime($now)+60*(int)$g['reservation_minutes']);if($g['expires_at']&&$g['expires_at']<$until)$until=$g['expires_at'];
        $this->exec('INSERT INTO group_orders(campaign_id,order_id,user_id,role,status,amount_cents,reserved_until,idempotency_key,created_at,updated_at) VALUES(?,?,?,?,"pending",?,?,?,?,?)',array($g['id'],$orderId,$g['member_user_id'],$g['member_role'],$promotion['discount'],$until,'group:'.$orderId,$now,$now));$seat=$this->pdo->lastInsertId();$this->exec('UPDATE group_members SET group_order_id=? WHERE id=?',array($seat,$g['member_id']));
    }
    // 资金和订单已由调用方锁定；资格不依赖 worker 是否及时执行。
    public function paymentGate($orderId){$this->transactionRequired();$r=$this->row('SELECT campaign_id FROM group_orders WHERE order_id=?',array($orderId));if(!$r)return null;$o=$this->row('SELECT product_type_snapshot FROM orders WHERE id=?',array($orderId));if(!$o||$o['product_type_snapshot']!=='vpn')throw new RuntimeException('账号订单不能参加拼团付款。');$g=$this->row('SELECT * FROM group_campaigns WHERE id=? FOR UPDATE',array($r['campaign_id']));if((int)$g['flow_version']!==2)return array('legacy'=>true,'valid'=>false,'group'=>$g);
        $seat=$this->row('SELECT * FROM group_orders WHERE order_id=? FOR UPDATE',array($orderId));$now=$this->now();return array('legacy'=>false,'valid'=>$this->usable($g,$now)&&$seat['status']==='pending'&&$seat['reserved_until']&&$now<$seat['reserved_until'],'group'=>$g,'seat'=>$seat);
    }
    public function markPaid($orderId,$gate){if(!$gate||!empty($gate['legacy']))return;$this->transactionRequired();$o=$this->row('SELECT product_type_snapshot FROM orders WHERE id=?',array($orderId));if(!$o||$o['product_type_snapshot']!=='vpn')throw new RuntimeException('账号订单不能结算拼团。');$g=$gate['group'];$now=$this->now();$this->exec('UPDATE group_orders SET status="paid",updated_at=? WHERE order_id=? AND status="pending"',array($now,$orderId));$this->exec('UPDATE group_members SET status="paid" WHERE campaign_id=? AND user_id=?',array($g['id'],$gate['seat']['user_id']));$count=(int)$g['current_members']+1;$success=$count>=(int)$g['target_members'];$this->exec('UPDATE group_campaigns SET current_members=?,status=?,successful_at=IF(?=1,?,successful_at),updated_at=? WHERE id=? AND status="forming"',array($count,$success?'successful':'forming',$success?1:0,$now,$now,$g['id']));}
    public function reverseOrder($orderId){$this->transactionRequired();$r=$this->row('SELECT campaign_id FROM group_orders WHERE order_id=?',array($orderId));if(!$r)return;$g=$this->row('SELECT * FROM group_campaigns WHERE id=? FOR UPDATE',array($r['campaign_id']));if((int)$g['flow_version']!==2)return;$seat=$this->row('SELECT * FROM group_orders WHERE order_id=? FOR UPDATE',array($orderId));if(!in_array($seat['status'],array('pending','paid','released'),true))return;$now=$this->now();$this->exec('UPDATE group_orders SET status="cancelled",close_reason="订单取消或退款",updated_at=? WHERE order_id=?',array($now,$orderId));$this->exec('UPDATE group_members SET status="cancelled",left_at=? WHERE campaign_id=? AND user_id=?',array($now,$g['id'],$seat['user_id']));
        if($g['status']==='forming')$this->exec('UPDATE group_campaigns SET reserved_members=GREATEST(CAST(reserved_members AS SIGNED)-1,0),current_members=GREATEST(CAST(current_members AS SIGNED)-?,0),updated_at=? WHERE id=?',array($seat['status']==='paid'?1:0,$now,$g['id']));
    }
    private function lockUsers($o){$ids=array((int)$o['user_id']);foreach($this->rows('SELECT referrer_user_id FROM referral_relations WHERE user_id=? AND status="active"',array($o['user_id'])) as $r)$ids[]=(int)$r['referrer_user_id'];foreach($this->rows('SELECT referrer_user_id FROM referral_commissions WHERE order_id=?',array($o['id'])) as $r)$ids[]=(int)$r['referrer_user_id'];$ids=array_unique($ids);sort($ids,SORT_NUMERIC);foreach($ids as $uid)$this->exec('SELECT id FROM users WHERE id=? FOR UPDATE',array($uid));}
    public function recordRefund($o,$payment,$reason){$this->transactionRequired();$channel=$payment['gateway_type']==='balance'?'balance':((int)$payment['amount_cents']===0?'zero':'external');$now=$this->now();$this->exec('INSERT INTO group_payment_refunds(payment_id,order_id,channel,status,amount_cents,reason,created_at,updated_at) VALUES(?,?,?,"pending",?,?,?,?) ON DUPLICATE KEY UPDATE payment_id=VALUES(payment_id)',array($payment['id'],$o['id'],$channel,$payment['amount_cents'],$reason,$now,$now));}
    // 本单退款资金阶段必须在团锁前完成；容量不足仅记录错误，保留可重试任务。
    private function refundFunds($o,$payment,$adminId=null){$r=$this->row('SELECT * FROM group_payment_refunds WHERE payment_id=? FOR UPDATE',array($payment['id']));if(!$r||$r['status']==='completed'||$r['channel']==='external')return $r;
        if($r['channel']==='balance'){$u=$this->row('SELECT balance_cents FROM users WHERE id=?',array($o['user_id']));$existing=$this->row('SELECT id FROM wallet_transactions WHERE idempotency_key=?',array('order_refund:'.$payment['id']));if(!$existing&&(int)$u['balance_cents']+(int)$payment['amount_cents']>WalletService::MAX_BALANCE_CENTS){$this->exec('UPDATE group_payment_refunds SET last_error="消费余额容量不足，等待重试",updated_at=NOW() WHERE id=?',array($r['id']));return $r;}(new WalletService($this->pdo))->refundOrder($o,$payment['id'],$adminId);}
        $this->exec('UPDATE group_payment_refunds SET status="completed",last_error="",processed_by=?,processed_at=NOW(),updated_at=NOW() WHERE id=?',array($adminId,$r['id']));$this->exec('UPDATE payment_records SET status="refunded",updated_at=NOW() WHERE id=?',array($payment['id']));$r['status']='completed';return $r;
    }
    public function processOrder($orderId){
        $this->pdo->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');
        $this->pdo->beginTransaction();try{
            $o=$this->row('SELECT * FROM orders WHERE id=? FOR UPDATE',array($orderId));if(!$o){$this->pdo->commit();return false;}$this->lockUsers($o);
            $payments=$this->rows('SELECT * FROM payment_records WHERE order_id=? ORDER BY id FOR UPDATE',array($orderId));$r=$this->row('SELECT campaign_id FROM group_orders WHERE order_id=?',array($orderId));if(!$r){$this->pdo->commit();return false;}
            // successful/failed 为不可逆事实；可在资金阶段无锁读取，然后最后重新锁团验证。
            $g=$this->row('SELECT * FROM group_campaigns WHERE id=?',array($r['campaign_id']));if((int)$g['flow_version']!==2){$this->pdo->commit();return false;}$now=$this->now();$seat=$this->row('SELECT * FROM group_orders WHERE order_id=?',array($orderId));$release=$g['status']==='successful'&&$o['status']==='paid_waiting_group'&&$seat['status']==='paid'&&!$seat['released_at'];
            if($release)(new OrderService($this->pdo))->releaseGroupDelivery($o);
            $refund=null;if($g['status']==='failed'&&in_array($o['status'],array('paid_waiting_group','refunding'),true))foreach($payments as $p)if((int)$p['id']===(int)$o['paid_payment_record_id']){$this->recordRefund($o,$p,'拼团到期未成团');$refund=$this->refundFunds($o,$p);}
            // 晚款/额外付款也逐条重试，不改变主订单的实际支付来源。
            foreach($payments as $p){$rr=$this->row('SELECT * FROM group_payment_refunds WHERE payment_id=?',array($p['id']));if($rr&&$rr['status']==='pending'&&(int)$p['id']!==(int)$o['paid_payment_record_id'])$this->refundFunds($o,$p);}
            if($o['status']==='pending_payment'&&($g['status']==='failed'||($seat['status']==='pending'&&$seat['reserved_until']&&$now>=$seat['reserved_until'])))$this->exec('UPDATE payment_records SET status="cancelled",updated_at=? WHERE order_id=? AND status="pending"',array($now,$orderId));
            $g=$this->row('SELECT * FROM group_campaigns WHERE id=? FOR UPDATE',array($g['id']));$seat=$this->row('SELECT * FROM group_orders WHERE order_id=? FOR UPDATE',array($orderId));
            if($release){$this->exec('UPDATE group_orders SET status="released",released_at=?,updated_at=? WHERE order_id=? AND released_at IS NULL',array($now,$now,$orderId));}
            elseif($refund){$done=$refund['status']==='completed';$this->exec('UPDATE orders SET status=?,refund_reason="拼团到期未成团",refund_processed_at=?,updated_at=? WHERE id=?',array($done?'refunded':'refunding',$done?$now:null,$now,$orderId));$this->exec('UPDATE group_orders SET status=?,close_reason="拼团到期未成团",updated_at=? WHERE order_id=?',array($done?'refunded':'refund_pending',$now,$orderId));}
            elseif($o['status']==='pending_payment'&&($g['status']==='failed'||($seat['status']==='pending'&&$seat['reserved_until']&&$now>=$seat['reserved_until']))){$this->exec('UPDATE orders SET status="cancelled",cancelled_at=?,cancel_reason="拼团付款占位已过期",updated_at=? WHERE id=?',array($now,$now,$orderId));$this->exec('UPDATE group_orders SET status="cancelled",close_reason="付款占位过期",updated_at=? WHERE order_id=?',array($now,$orderId));$this->exec('UPDATE group_members SET status="cancelled",left_at=? WHERE campaign_id=? AND user_id=?',array($now,$g['id'],$o['user_id']));if($g['status']==='forming'){$n=$this->row('SELECT COUNT(*) n FROM group_orders WHERE campaign_id=? AND (status IN ("paid","released") OR (status="pending" AND NOW()<reserved_until))',array($g['id']));$this->exec('UPDATE group_campaigns SET reserved_members=?,updated_at=? WHERE id=?',array($n['n'],$now,$g['id']));}}
            $this->exec('UPDATE group_orders SET worker_checked_at=NOW(6) WHERE order_id=?',array($orderId));
            $this->pdo->commit();return true;
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
    public function runOnce($limit=100){$limit=max(1,min(1000,(int)$limit));$result=array('groups'=>0,'orders'=>0,'errors'=>array());
        foreach($this->rows('SELECT id FROM group_campaigns WHERE flow_version=2 AND status="forming" AND expires_at<=NOW() ORDER BY id LIMIT '.$limit) as $r){$this->pdo->beginTransaction();try{$s=$this->exec('UPDATE group_campaigns SET status="failed",failed_at=NOW(),updated_at=NOW() WHERE id=? AND flow_version=2 AND status="forming" AND expires_at<=NOW()',array($r['id']));$result['groups']+=$s->rowCount();$this->pdo->commit();}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();$result['errors'][]=$e->getMessage();}}
        $ids=$this->rows('SELECT go.order_id FROM group_orders go JOIN group_campaigns g ON g.id=go.campaign_id WHERE g.flow_version=2 AND ((g.status="successful" AND go.status="paid" AND go.released_at IS NULL) OR (g.status="failed" AND (go.status IN ("pending","paid") OR (go.status="refund_pending" AND EXISTS(SELECT 1 FROM group_payment_refunds pr WHERE pr.order_id=go.order_id AND pr.status="pending" AND pr.channel<>"external")))) OR (go.status="pending" AND go.reserved_until<=NOW()) OR EXISTS(SELECT 1 FROM group_payment_refunds r WHERE r.order_id=go.order_id AND r.status="pending" AND r.channel<>"external")) ORDER BY go.worker_checked_at,go.order_id LIMIT '.$limit);
        foreach($ids as $r)try{$this->processOrder($r['order_id']);$result['orders']++;}catch(Throwable $e){
            $result['errors'][]='订单 '.$r['order_id'].'：'.$e->getMessage();
            // 业务事务已回滚；单独短事务只推进调度标记，毒任务不得永久占据队首。
            try{$this->pdo->beginTransaction();$this->exec('SELECT id FROM orders WHERE id=? FOR UPDATE',array($r['order_id']));$c=$this->row('SELECT campaign_id FROM group_orders WHERE order_id=?',array($r['order_id']));if($c){$this->exec('SELECT id FROM group_campaigns WHERE id=? FOR UPDATE',array($c['campaign_id']));$this->exec('UPDATE group_orders SET worker_checked_at=NOW(6) WHERE order_id=?',array($r['order_id']));}$this->pdo->commit();}catch(Throwable $scheduleError){if($this->pdo->inTransaction())$this->pdo->rollBack();$result['errors'][]='调度标记写入失败：'.$scheduleError->getMessage();}
        }return $result;
    }
    private function admin($id){if(!$this->row('SELECT id FROM admin_users WHERE id=? AND status="active"',array($id)))throw new RuntimeException('管理员身份无效。');}
    public function retryRefund($id,$adminId){$this->admin($adminId);$r=$this->row('SELECT * FROM group_payment_refunds WHERE id=?',array($id));if(!$r||$r['channel']==='external')throw new RuntimeException('仅余额自动退款可重试。');return $this->processOrder($r['order_id']);}
    public function confirmExternalRefund($id,$adminId,$reference,$note=''){
        if(trim($reference)===''||strlen($reference)>190)throw new InvalidArgumentException('请填写有效的原渠道退款凭证。');$this->admin($adminId);$this->pdo->beginTransaction();try{
            $r=$this->row('SELECT * FROM group_payment_refunds WHERE id=?',array($id));if(!$r)throw new RuntimeException('退款记录不存在。');$o=$this->row('SELECT * FROM orders WHERE id=? FOR UPDATE',array($r['order_id']));$this->lockUsers($o);$p=$this->row('SELECT * FROM payment_records WHERE id=? FOR UPDATE',array($r['payment_id']));$r=$this->row('SELECT * FROM group_payment_refunds WHERE id=? FOR UPDATE',array($id));
            if($r['channel']!=='external'||!in_array($r['status'],array('pending','completed'),true))throw new RuntimeException('不是待处理的原渠道退款。');if($r['status']==='completed'){$this->pdo->commit();return true;}
            $this->exec('UPDATE group_payment_refunds SET status="completed",external_reference=?,processed_by=?,processed_at=NOW(),updated_at=NOW(),last_error="" WHERE id=?',array(trim($reference),$adminId,$id));$this->exec('UPDATE payment_records SET status="refunded",updated_at=NOW() WHERE id=?',array($p['id']));
            $this->exec('INSERT INTO admin_logs(admin_id,action,target_type,target_id,details_json,created_at) VALUES(?,"group_external_refund","group_payment_refund",?,?,NOW())',array($adminId,$id,json_encode(array('payment_id'=>$p['id'],'amount_cents'=>$r['amount_cents'],'reference'=>$reference,'note'=>substr($note,0,500)),JSON_UNESCAPED_UNICODE)));
            if((int)$o['paid_payment_record_id']===(int)$p['id']&&$o['status']==='refunding'){$this->exec('UPDATE orders SET status="refunded",refund_processed_at=NOW(),updated_at=NOW() WHERE id=?',array($o['id']));$g=$this->row('SELECT campaign_id FROM group_orders WHERE order_id=?',array($o['id']));if($g){$this->exec('SELECT id FROM group_campaigns WHERE id=? FOR UPDATE',array($g['campaign_id']));$this->exec('UPDATE group_orders SET status="refunded",updated_at=NOW() WHERE order_id=?',array($o['id']));}}
            $this->pdo->commit();return true;
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
    public function listing($uid=0,$page=1,$perPage=9){return $this->page(false,$uid,$page,$perPage);}
    public function mine($uid,$page=1,$perPage=10){return $this->page(true,$uid,$page,$perPage);}
    private function page($mine,$uid,$page,$perPage){$perPage=max(1,min(50,(int)$perPage));$where=$mine?'EXISTS(SELECT 1 FROM group_members m WHERE m.campaign_id=g.id AND m.user_id=?)':'g.flow_version=2 AND g.status="forming" AND (g.expires_at IS NULL OR NOW()<g.expires_at)';$args=$mine?array($uid):array();$n=$this->row('SELECT COUNT(*) n FROM group_campaigns g WHERE '.$where,$args);$pages=max(1,(int)ceil($n['n']/$perPage));$page=max(1,min($pages,(int)$page));$items=$this->rows('SELECT g.* FROM group_campaigns g WHERE '.$where.' ORDER BY id DESC LIMIT '.$perPage.' OFFSET '.(($page-1)*$perPage),$args);foreach($items as &$g)$g=$this->displayGroup($g);unset($g);return array('items'=>$items,'total'=>(int)$n['n'],'page'=>$page,'pages'=>$pages);}
    private function displayGroup($g){$n=$this->row('SELECT COUNT(*) n FROM group_orders WHERE campaign_id=? AND (status IN ("paid","released") OR (status="pending" AND NOW()<reserved_until))',array($g['id']));$g['remaining_seats']=max(0,(int)$g['target_members']-(int)$n['n']);$g['can_join']=$this->usable($g,$this->now())&&$g['remaining_seats']>0&&$this->activityEnabled();return $g;}
    public function detail($id,$uid=0){$g=$this->row('SELECT * FROM group_campaigns WHERE id=?',array($id));if(!$g)return null;$g=$this->displayGroup($g);$plans=(new ActivityService($this->pdo))->allowedGroupPlans($id);foreach($plans as &$plan){$amount=(int)$plan['price_cents'];$percent=(int)$g['discount_percent_snapshot'];$plan['group_price_cents']=intdiv($amount,100)*$percent+intdiv(($amount%100)*$percent,100);$plan['discount_percent_snapshot']=$percent;}unset($plan);$member=$uid?$this->row('SELECT * FROM group_members WHERE campaign_id=? AND user_id=?',array($id,$uid)):null;$order=$uid?$this->row('SELECT o.* FROM orders o JOIN group_orders go ON go.order_id=o.id WHERE go.campaign_id=? AND go.user_id=?',array($id,$uid)):null;$members=$this->rows('SELECT role,status FROM group_members WHERE campaign_id=? ORDER BY id',array($id));foreach($members as &$m)$m['display_name']='拼友';unset($m);return array('group'=>$g,'plans'=>$plans,'member'=>$member,'order'=>$order,'members'=>$members);}
    public function orderContext($orderId,$uid=null){$o=$this->row('SELECT user_id FROM orders WHERE id=?',array($orderId));if(!$o||($uid!==null&&(int)$o['user_id']!==(int)$uid))return null;$seat=$this->row('SELECT * FROM group_orders WHERE order_id=?',array($orderId));if(!$seat)return null;$g=$this->row('SELECT * FROM group_campaigns WHERE id=?',array($seat['campaign_id']));$r=$seat;$r['group']=$this->displayGroup($g);$r['seat']=$seat;$r['flow_version']=$g['flow_version'];$r['group_status']=$g['status'];$r['refunds']=$this->rows('SELECT * FROM group_payment_refunds WHERE order_id=? ORDER BY id',array($orderId));return $r;}
}
